def compute(vars):
    employees_terminated = vars["v1"]
    workforce_percentage = vars["v2"]

    if workforce_percentage == 0:
        return None

    workforce_fraction = workforce_percentage / 100
    total_workforce = employees_terminated / workforce_fraction

    return {
        "value": total_workforce,
        "trace": {
            "employees_terminated": employees_terminated,
            "workforce_percentage": workforce_percentage,
            "workforce_fraction": workforce_fraction,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "employees"
            }
        }
    }
